"""Render results/RESULTS.md from results/metrics.json so no number is typed by hand."""
from __future__ import annotations

import json
from pathlib import Path

from .plots import LABEL

ROOT = Path(__file__).resolve().parents[2]


def f(x, d=3):
    return "—" if x is None else f"{x:.{d}f}"


def main():
    m = json.loads((ROOT / "results/metrics.json").read_text())
    ds, best = m["dataset"], m["selected_model"]
    L = ["# Results", "",
         "_Generated by `python -m fraud.make_report` from [`metrics.json`](metrics.json). Do not edit by hand._", "",
         "## Data", "",
         f"- Rows after dropping {ds['exact_duplicates_dropped']:,} exact duplicates: **{ds['rows']:,}** "
         f"({ds['frauds']} frauds, {100 * ds['fraud_rate']:.3f}%)",
         f"- SHA-256 matches public release: **{ds['sha256_matches_public_release']}**",
         f"- Split: {ds['split']['protocol']} — train {ds['split']['train']['rows']:,} "
         f"({ds['split']['train']['frauds']} frauds), validation {ds['split']['val']['rows']:,} "
         f"({ds['split']['val']['frauds']}), test {ds['split']['test']['rows']:,} ({ds['split']['test']['frauds']})", "",
         "## Model comparison (test = final 20% of time; thresholds chosen on validation)", "",
         "| Model | Test PR-AUC (seed 0) | 95% CI | Mean ± SD over seeds | ROC-AUC | Precision | Recall | Recall 95% CI | Alerts / 1k tx |",
         "|---|---|---|---|---|---|---|---|---|"]
    order = sorted(m["models"], key=lambda k: -m["models"][k]["runs"][0]["test"]["pr_auc"])
    for k in order:
        r = m["models"][k]
        r0 = r["runs"][0]
        t = r0["test_at_val_f1_threshold"]
        b = m["bootstrap_ci95_seed0"][k]
        sel = " **(selected on val)**" if k == best else ""
        L.append(f"| {LABEL[k]}{sel} | {f(r0['test']['pr_auc'])} | {f(b['pr_auc'][0])}–{f(b['pr_auc'][1])} | "
                 f"{f(r['test_pr_auc_mean'])} ± {f(r['test_pr_auc_sd'])} (n={r['n_seeds']}) | {f(r0['test']['roc_auc'])} | "
                 f"{f(t['precision'])} | {f(t['recall'])} | {f(b['recall'][0])}–{f(b['recall'][1])} | {f(t['alerts_per_1k'], 2)} |")
    L += ["", "## Paired bootstrap comparisons (test PR-AUC, seed 0)", "",
          "| Comparison | Mean difference | 95% CI | Share of resamples where first is not better |", "|---|---|---|---|"]
    for k, v in m["paired_bootstrap_pr_auc"].items():
        L.append(f"| {k} | {v['mean']:+.3f} | {v['ci95'][0]:+.3f} – {v['ci95'][1]:+.3f} | {v['p_a_not_better']:.3f} |")
    c = m["calibration"]
    L += ["", f"## Calibration ({LABEL[c['model']]})", "",
          "| | Brier | ECE (15 equal-mass bins) | PR-AUC |", "|---|---|---|---|",
          f"| Uncalibrated | {c['uncalibrated_test']['brier']:.5f} | {c['uncalibrated_test']['ece']:.5f} | {f(c['uncalibrated_test']['pr_auc'])} |",
          f"| Isotonic (fit on validation) | {c['isotonic_test']['brier']:.5f} | {c['isotonic_test']['ece']:.5f} | {f(c['isotonic_test']['pr_auc'])} |",
          "", f"## Review-cost sensitivity ({LABEL[best]})", "",
          "Threshold minimises `missed fraud amount + review_cost × alerts` on validation, then is applied to test.", "",
          "| Review cost (EUR) | Precision | Recall | Share of fraud amount caught | Alerts / 1k tx |", "|---|---|---|---|---|"]
    for r in m["review_cost_sensitivity"]:
        L.append(f"| {r['review_cost']:g} | {f(r['precision'])} | {f(r['recall'])} | {f(r['fraud_amount_caught_share'])} | {f(r['alerts_per_1k'], 2)} |")
    L += ["", "## Random vs temporal split", "",
          "| Model | Temporal test PR-AUC (mean) | Stratified-random test PR-AUC (mean ± SD) |", "|---|---|---|"]
    for k, v in m["random_vs_temporal_split"].items():
        L.append(f"| {LABEL[k]} | {f(v['temporal_pr_auc_mean'])} | {f(v['pr_auc_mean'])} ± {f(v['pr_auc_sd'])} |")
    e = m["error_analysis"]
    L += ["", f"## Error analysis ({LABEL[e['model']]}, val-F1 threshold {e['threshold']:.3f})", "",
          f"- Median amount of caught frauds: {f(e['fraud_amount_median_caught'], 2)} EUR; "
          f"missed frauds: {f(e['fraud_amount_median_missed'], 2)} EUR; false alarms: {f(e['false_positive_amount_median'], 2)} EUR", "",
          "| Amount range (EUR) | Frauds | Caught | Recall |", "|---|---|---|---|"]
    for r in e["recall_by_amount"]:
        L.append(f"| {r['amount_range']} | {r['frauds']} | {r['caught']} | {f(r['recall'])} |")
    if e.get("top_features_gain"):
        L += ["", "Top features by gain: " + ", ".join(f"{n} ({v:.3f})" for n, v in e["top_features_gain"])]
    env = m["environment"]
    L += ["", "## Environment", "",
          f"Python {env['python']}, scikit-learn {env['sklearn']}, XGBoost {env['xgboost']}, {env['platform']}; "
          f"{env['n_seeds']} seeds, {env['n_bootstrap']} bootstrap resamples; runtime {env['runtime_seconds']} s (CPU)."]
    (ROOT / "results/RESULTS.md").write_text("\n".join(L) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
